#ifndef FILE_WINDOW_H
#define FILE_WINDOW_H

#include <stdbool.h>
#include <stdint.h>

/* -----------------------------------------------------------------------
 * file_window.h
 * TEAM CODE (owner: Tony - display and user interface) - written by the BJT2 team, not generated by STM32CubeMX.
 * Authors: written by Brendon (integrator) on 29-30 Oct 2026 for Tony's display/UI subsystem (best-ui), with an AI coding assistant.
 * BJT2 Sound Modulating Toy — File List Window
 *
 * What it does: the card can hold hundreds of recordings, but one
 * message from Jack carries only 16 names. This module keeps those 16
 * names (a "window" over the whole list), answers "which name is at
 * list position i?", and says when the UI should ask Jack for another
 * window because the selection is close to an edge.
 *
 *     whole list (card order):  0 1 2 ... 31 [32 ............ 47] 48 ... 119
 *     window (one reply):                    first = 32, count = 16
 *     the File screen shows file_index 40 -> "F040.WAV" from the window
 *
 * Who runs it: TonyTask, through tony_ui.c (one window, s_win). Pure
 * logic: no RTOS, no HAL, so it compiles on any host (tests:
 * test_file_window.c). The names are kept RAW, byte for byte as Jack
 * sent them: PLAY and Delete send them back to Jack, so a name with a
 * code page 850 letter must not be turned into '?' here. Only a copy is
 * cleaned up for drawing (sv_sanitize in tony_ui.c).
 *
 * Main steps:
 *   1. fw_apply()      a StorageReply_t arrived: keep its window (where
 *                      it sits in the list), then fw_apply_name() for
 *                      each of its names
 *   2. fw_name()       the raw name at a list position, or NULL outside
 *                      the window; fw_sel_name() copies it for the glue
 *   3. fw_wants()      the selection is outside the window, or within
 *                      FW_MARGIN of an edge with more names beyond it:
 *                      ask Jack for the window around it
 *   4. fw_stale()      Jack's list changed since: his status has a newer
 *                      list_gen than the window
 *   5. fw_invalidate() the card went: forget everything, so the next
 *                      card starts at its own last file
 * ----------------------------------------------------------------------- */

#define FW_NAMES        16U     /* names in one window (= STORAGE_MAX_LISTED_FILES, app_rtos.h) */
#define FW_NAME_LEN     13U     /* an 8.3 name + NUL (= STORAGE_NAME_LEN, app_rtos.h) */
#define FW_MARGIN       3U      /* ask for the next window when the selection is this close to an
                                 * edge: one reply can take 100 ms or more, so the names arrive
                                 * before the knob reaches the edge */

typedef struct {
    uint16_t first;                         /* list position of names[0] */
    uint16_t total;                         /* files in the whole list */
    uint16_t gen;                           /* Jack's list_gen the names were read from */
    uint8_t  count;                         /* names[] in use, 0..FW_NAMES */
    bool     valid;                         /* names[] hold a window */
    bool     ever;                          /* a window has arrived since the card came */
    char     names[FW_NAMES][FW_NAME_LEN];  /* raw 8.3 names, in card order */
} fw_window_t;

/**
 * fw_init
 * No window: not valid, not ever. NULL: nothing happens.
 */
void fw_init(fw_window_t *w);

/**
 * fw_apply
 * Start keeping the window of one StorageReply_t: names[i] will be list
 * position first + i (fw_apply_name() fills them in). At most FW_NAMES
 * names are kept. Sets valid and ever (also for an empty list). NULL w:
 * nothing happens.
 *
 * @param first  List position of the reply's names[0].
 * @param count  Names in use.
 * @param total  Files in the whole list.
 * @param gen    The reply's list_gen.
 */
void fw_apply(fw_window_t *w, uint16_t first, uint8_t count, uint16_t total, uint16_t gen);

/**
 * fw_apply_name
 * names[i] of the window, copied byte for byte (raw: a byte of 0x80 or
 * more stays as it is) up to its NUL or 12 characters, and always ended
 * with a NUL. An i past the window's count, a NULL w or a NULL name
 * changes nothing.
 */
void fw_apply_name(fw_window_t *w, uint8_t i, const char *name);

/**
 * fw_name
 * The raw name at list position index, or NULL when index is outside the
 * window (or there is no window).
 */
const char *fw_name(const fw_window_t *w, uint16_t index);

/**
 * fw_sel_name
 * Copies fw_name(w, index) into out (FW_NAME_LEN bytes), or "" when it is
 * NULL. NULL out: nothing happens.
 */
void fw_sel_name(const fw_window_t *w, uint16_t index, char out[FW_NAME_LEN]);

/**
 * fw_wants
 * Should the UI ask Jack for the window around index? true when:
 *   - no window is loaded,
 *   - index is outside the window, or
 *   - index is within FW_MARGIN of an edge beyond which the list has
 *     more names.
 * false for an empty list (there is nothing more to show) and for NULL.
 */
bool fw_wants(const fw_window_t *w, uint16_t index);

/**
 * fw_stale
 * true when a window is loaded and was read from an OLDER list_gen than
 * gen (Jack's newest status): the list has changed since (a recording,
 * a delete, a rescan), so the names may have moved. A window read from a
 * NEWER list_gen than gen is not stale: the File screen's own LIST_FILES
 * rescan moves list_gen on, and Jack's reply can arrive before a status
 * with the new number. Also right when list_gen rolls over from 65535 to 0.
 */
bool fw_stale(const fw_window_t *w, uint16_t gen);

/**
 * fw_invalidate
 * The card went (pulled, unmounted or handed to a PC): forget the window
 * and clear ever. NULL: nothing happens.
 */
void fw_invalidate(fw_window_t *w);

/**
 * fw_ever
 * true once a window has arrived since the card came (fw_apply after the
 * last fw_invalidate). PLAY from Home with no window yet plays the last
 * file of the list (STORAGE_INDEX_LAST) instead of an old card's name.
 */
bool fw_ever(const fw_window_t *w);

#endif /* FILE_WINDOW_H */
